const fs = require('fs');

const START = '<!-- showscape:start -->';
const END = '<!-- showscape:end -->';
const BANNER = '<p align="center"><b>Built with Showscape</b></p>';

function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8');
  } catch (err) {
    if (err.code === 'EOF' || err.code === 'EAGAIN') return '';
    throw err;
  }
}

function stripBanner(text) {
  const s = text.indexOf(START);
  if (s === -1) return text;
  const e = text.indexOf(END, s);
  if (e === -1) return text;

  let cut = e + END.length;
  if (text.startsWith('\r\n', cut)) cut += 2;
  else if (text[cut] === '\n') cut += 1;

  return text.slice(0, s) + text.slice(cut);
}

function addBanner(text) {
  return START + '\n' + BANNER + '\n' + END + '\n' + text;
}

function transform(mode, text) {
  if (mode === 'clean') return addBanner(stripBanner(text));
  if (mode === 'smudge') return stripBanner(text);
  return text;
}

function run(mode) {
  const text = readStdin();
  process.stdout.write(transform(mode, text));
}

module.exports = { run, transform, stripBanner, addBanner };
